import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  it('reuses a static schema validator across executions', async () => {
    const registry = new ToolRegistry();
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema,
      },
      async () => 'sunny'
    );

    inputSchema.type = 'not-a-schema-type';
    const responses = await Promise.all(
      Array.from({length: 10}, () => registry.execute('get_weather', {location: 'Paris'}))
    );

    expect(responses).toEqual(Array.from({length: 10}, () => ({result: 'sunny'})));
  });

  it('passes valid input with undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', requestId: 'opaque-id'};
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather_with_metadata',
        description: 'Get weather with request metadata',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async receivedInput => {
        executorInputs.push(receivedInput);
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather_with_metadata', input);

    expect({response, executorInputs}).toEqual({
      response: {result: 'sunny'},
      executorInputs: [input],
    });
  });

  it('validates a function-valued definition against the schema returned for each call', async () => {
    const registry = new ToolRegistry();
    let requiredField = 'location';
    const executorInputs: Array<Record<string, unknown>> = [];

    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Get weather with a dynamic schema',
        inputSchema: {
          type: 'object',
          properties: {[requiredField]: {type: 'string'}},
          required: [requiredField],
        },
      }),
      async input => {
        executorInputs.push(input);
        return 'sunny';
      }
    );

    const firstResponse = await registry.execute('dynamic_weather', {location: 'Paris'});
    requiredField = 'city';
    const secondResponse = await registry.execute('dynamic_weather', {city: 'Berlin'});

    expect({firstResponse, secondResponse, executorInputs}).toEqual({
      firstResponse: {result: 'sunny'},
      secondResponse: {result: 'sunny'},
      executorInputs: [{location: 'Paris'}, {city: 'Berlin'}],
    });
  });

  it('names the complete path for a nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_weather',
        description: 'Get weather with nested location data',
        inputSchema: {
          type: 'object',
          properties: {
            location: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('nested_weather', {location: {}});

    expect(response.result).toMatch(/location\.city is required/);
  });

  it('names the field path for a wrong-typed property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'typed_weather',
        description: 'Get typed weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('typed_weather', {location: 42});

    expect({
      namesField: response.result.includes('location'),
      namesExpectedType: response.result.includes('string'),
      omitsOffendingValue: !response.result.includes('42'),
    }).toEqual({
      namesField: true,
      namesExpectedType: true,
      omitsOffendingValue: true,
    });
  });

  it('names enum as the failed constraint without echoing the rejected value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'enum_weather',
        description: 'Get weather with a supported unit',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('enum_weather', {unit: 'kelvin'});

    expect({
      namesField: response.result.includes('unit'),
      namesConstraint: response.result.includes('enum'),
      omitsOffendingValue: !response.result.includes('kelvin'),
    }).toEqual({
      namesField: true,
      namesConstraint: true,
      omitsOffendingValue: true,
    });
  });

  it('throws the unchanged error for an unregistered tool', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_weather', {})).rejects.toThrow('Unknown tool: missing_weather');
  });

  it('names the tool when a null static schema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'invalid_weather',
          description: 'Invalid weather schema',
          inputSchema: null as unknown as Record<string, unknown>,
        },
        async () => 'sunny'
      )
    ).toThrow('Invalid inputSchema for tool invalid_weather');
  });
});

